CREATE OR REPLACE FUNCTION public.send_qr_message(p_user uuid,recipient_mailbox uuid,encrypted_text text,message_nonce text,ephemeral_key text,message_kind text DEFAULT 'text') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE recipient uuid; mid uuid; trial timestamptz; paid timestamptz; BEGIN IF NOT EXISTS(SELECT 1 FROM device_qr_credentials WHERE mailbox_user=p_user) THEN RAISE EXCEPTION 'Access required'; END IF; SELECT trial_started_at INTO trial FROM private_mailboxes WHERE user_id=p_user; SELECT user_id INTO recipient FROM private_mailboxes WHERE mailbox_id=recipient_mailbox; IF recipient IS NULL OR trial IS NULL THEN RAISE EXCEPTION 'Mailbox unavailable'; END IF; SELECT COALESCE(CASE WHEN u.is_subscription_active AND u.subscription_renews_at>now() THEN u.subscription_renews_at END,u.trial_expires_at) INTO paid FROM device_qr_credentials q JOIN users u ON u.credential_handle=q.wallet::text WHERE q.mailbox_user=p_user; IF message_kind<>'text' AND now()>=trial+interval '7 days' AND (paid IS NULL OR paid<=now()) AND public.private_message_paid_until(p_user) IS NULL AND NOT EXISTS(SELECT 1 FROM private_message_reply_access r WHERE r.recipient_id=p_user AND r.paid_sender_id=recipient AND public.private_message_paid_until(recipient)>now()) THEN RAISE EXCEPTION 'Audio access expired'; END IF; IF EXISTS(SELECT 1 FROM private_message_blocks WHERE (user_id=recipient AND blocked_id=p_user) OR (user_id=p_user AND blocked_id=recipient)) THEN RAISE EXCEPTION 'Recipient unavailable'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(p_user::text,0)); IF (SELECT count(*) FROM private_message_envelopes WHERE sender_id=p_user AND created_at>now()-interval '1 minute')>=10 THEN RAISE EXCEPTION 'Please wait'; END IF; INSERT INTO private_message_envelopes(sender_id,recipient_id,ciphertext,nonce,sender_key,kind) VALUES(p_user,recipient,encrypted_text,message_nonce,ephemeral_key,message_kind) RETURNING id INTO mid; RETURN mid; END; $$;
REVOKE ALL ON FUNCTION public.send_qr_message(uuid,uuid,text,text,text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.send_qr_message(uuid,uuid,text,text,text,text) TO service_role;
CREATE OR REPLACE FUNCTION public.consume_qr_message(p_user uuid,p_message uuid) RETURNS TABLE(ciphertext text,nonce text,sender_key text,kind text) LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ DELETE FROM private_message_envelopes e WHERE e.id=p_message AND e.recipient_id=p_user AND e.expires_at>now() AND EXISTS(SELECT 1 FROM device_qr_credentials WHERE mailbox_user=p_user) RETURNING e.ciphertext,e.nonce,e.sender_key,e.kind; $$;
REVOKE ALL ON FUNCTION public.consume_qr_message(uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.consume_qr_message(uuid,uuid) TO service_role;